mapper.update:
UPDATE sys_task_lease
SET task_id = #{taskId},
    idempotency_key = #{idempotencyKey},
    attempt = attempt + 1,
    lease_expires_at = #{leaseExpiresAt},
    status = 'RUNNING',
    failure_digest = NULL,
    updated_at = #{now}
WHERE task_type = #{taskType}
  AND lease_expires_at <= #{now}

mapper.select:
SELECT task_id, task_type, idempotency_key, attempt, lease_expires_at
FROM sys_task_lease
WHERE task_type = #{taskType}

mapper.update:
UPDATE sys_task_lease
SET status = 'SUCCEEDED', lease_expires_at = #{now}, updated_at = #{now}
WHERE task_type = #{lease.taskType} AND task_id = #{lease.taskId}

UPDATE sys_task_lease
SET status = 'RETRY', failure_digest = #{failureDigest},
    lease_expires_at = #{leaseExpiresAt}, updated_at = #{now}
WHERE task_type = #{lease.taskType} AND task_id = #{lease.taskId}

UPDATE sys_task_lease
SET status = 'FAILED_MANUAL', failure_digest = #{failureDigest},
    lease_expires_at = #{now}, updated_at = #{now}
WHERE task_type = #{lease.taskType} AND task_id = #{lease.taskId}
